import { motion } from 'framer-motion';
import { Award as AwardIcon, ExternalLink } from 'lucide-react';

import type { Award } from '../../hooks/useAwards';

interface AwardCardProps {
  award: Award;
  index: number;
}

export default function AwardCard({ award, index }: AwardCardProps) {
  const formattedDate = new Date(award.date).getFullYear().toString();

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: index * 0.1 }}
      className="group bg-white dark:bg-neutral-dark rounded-xl p-6 shadow-lg hover:shadow-xl transition-all"
    >
      <div className="flex items-center justify-between mb-4">
        <AwardIcon className="w-8 h-8 text-primary dark:text-primary-light" />
        <span className="text-sm font-medium text-neutral-dark/70 dark:text-white/70">
          {formattedDate}
        </span>
      </div>

      <h3 className="text-xl font-bold text-neutral-dark dark:text-white mb-2 group-hover:text-primary dark:group-hover:text-primary-light transition-colors">
        {award.title}
      </h3>

      <div className="flex items-center gap-2 mb-2">
        <span className="text-sm font-medium text-neutral-dark/70 dark:text-white/70">Client:</span>
        <span className="text-sm font-semibold text-primary dark:text-primary-light">
          {award.issuer}
        </span>
      </div>

      <p className="text-neutral-dark/70 dark:text-white/70 mb-4">{award.description}</p>

      {award.link && (
        <motion.a
          href={award.link}
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex items-center gap-2 text-sm text-primary dark:text-primary-light hover:text-primary-dark dark:hover:text-primary group"
          whileHover={{ x: 4 }}
          transition={{ duration: 0.2 }}
        >
          Award
          <ExternalLink className="w-4 h-4 transform transition-transform group-hover:scale-110" />
        </motion.a>
      )}
    </motion.div>
  );
}
